async function object(id, version=null) { if (!id) return null; const key=version ? `${id}@${version}` : id; const current = app.state?.objects.find(item => item.id === id); const cached = app.cache.get(key); if (cached && (version || !current || cached.version === current.version)) return cached; const result = await api(`/api/object/${encodeURIComponent(id)}${version ? '?version='+Number(version) : ''}`); app.cache.set(key,result); return result; }
