function uniqueIds(value) { const values=[]; const visit=(x) => { if (typeof x === 'string' && /^(dataset|discovery|behavior|protocol|experiment|evaluation|theory|network_protocol|network_experiment|complementary_protocol|complementary_experiment|resource_protocol|resource_experiment|name_eligibility_audit|measurement_audit|measurement_sample|measurement_review|graph_measurement_audit|selected_lead_audit|temporal_path_audit|temporal_timestamp_reference|source_link_audit|event_source_index|indexed_event_audit|actor_event_audit|wait_marker_alignment_audit|graph_hodge_audit|timed_resource_protocol|timed_resource_experiment|revision_relay_protocol|revision_relay_experiment|verification|claim_audit|replication|environment_blueprint|environment_construction_attempt|research_cycle)-/.test(x)) values.push(x); else if (Array.isArray(x)) x.forEach(visit); else if (x && typeof x === 'object') Object.values(x).forEach(visit); }; visit(value); return [...new Set(values)]; }
