function episodeRef(value) {
  if(!value || typeof value.id!=='string' || !/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(value.id) || !Number.isSafeInteger(value.version) || value.version<1 || value.version>1000000000 || typeof value.hash!=='string' || !/^[0-9a-f]{64}$/.test(value.hash))throw new Error('Use the exact saved episode source version and hash.');
  return {id:value.id,version:value.version,hash:value.hash};
}
function episodeSameRef(left,right) { return !!left && !!right && left.id===right.id && left.version===right.version && left.hash===right.hash; }
function episodeButton(discovery,leadId,behavior=null) {
  if(!String(leadId || '').startsWith('graph-lead-'))return '';
  try { const ref=episodeRef(discovery), b=behavior ? episodeRef(behavior) : null;
    return `<button class="button" data-episode-lead="${esc(leadId)}" data-episode-discovery="${esc(ref.id)}" data-episode-discovery-version="${ref.version}" data-episode-discovery-hash="${esc(ref.hash)}" ${b ? `data-episode-behavior="${esc(b.id)}" data-episode-behavior-version="${b.version}" data-episode-behavior-hash="${esc(b.hash)}"` : ''}>Open episode workspace →</button>`;
  } catch(_) { return ''; }
}
async function openEpisodeWorkspace(discoveryRef,leadId,behaviorRef=null) {
  const expectedDiscovery=episodeRef(discoveryRef), discovery=await object(expectedDiscovery.id,expectedDiscovery.version);
  if(discovery?.kind!=='discovery' || !episodeSameRef(discovery,expectedDiscovery))throw new Error('The exact discovery source does not match this episode.');
  const datasetRef=episodeRef(discovery.payload.dataset_ref), candidate=discovery.payload.candidates.find(row=>row.id===leadId);
  if(!candidate?.window_id || !candidate.comparison_window_id)throw new Error('This candidate has no registered graph-window comparison.');
  const relevant=(ref,anchor)=>ref?.id===anchor.id && ref?.version===anchor.version;
  const selectedRows=await Promise.all(all('selected_lead_audit').slice(0,8).map(row=>object(row.id,row.version)));
  const selectedAudit=selectedRows.find(row=>relevant(row.payload?.source_refs?.discovery,expectedDiscovery));
  if(!selectedAudit)throw new Error('No selected-lead audit for this exact discovery is in the bounded workspace inventory. Open Observatory and audit this source first.');
  if(!episodeSameRef(selectedAudit.payload.source_refs.discovery,expectedDiscovery) || !episodeSameRef(selectedAudit.payload.source_refs.dataset,datasetRef))throw new Error('The newest relevant selected-lead audit has a different source binding.');
  const selectedRef=episodeRef(selectedAudit), temporalRows=await Promise.all(all('temporal_path_audit').slice(0,8).map(row=>object(row.id,row.version)));
  const temporalAudit=temporalRows.find(row=>relevant(row.payload?.selected_audit_ref,selectedRef));
  if(!temporalAudit)throw new Error('No temporal audit for this exact selected-lead version is in the bounded inventory. Audit its temporal paths first.');
  if(!episodeSameRef(temporalAudit.payload.selected_audit_ref,selectedRef))throw new Error('The newest relevant temporal audit has a different source binding.');
  const comparison=Object.fromEntries(['id','feature','window_id','comparison_window_id'].map(key=>[key,candidate[key]]));
  const expected={source_refs:{dataset:datasetRef,discovery:expectedDiscovery,selected_audit:selectedRef,temporal_audit:episodeRef(temporalAudit)},lead_id:leadId,comparison};
  const params=new URLSearchParams({selected_audit_id:selectedAudit.id,selected_audit_version:String(selectedAudit.version),temporal_audit_id:temporalAudit.id,temporal_audit_version:String(temporalAudit.version),lead_id:leadId});
  if(behaviorRef) { const b=episodeRef(behaviorRef); params.set('behavior_id',b.id);params.set('behavior_version',String(b.version));expected.behavior_ref=b; }
  const packet=await api('/api/episode-workspace?'+params.toString());
  if(EpisodeWorkspace.validate(packet,expected).available!==true)throw new Error(packet.reason || 'The returned episode packet does not match the exact selected source.');
  if(behaviorRef && packet.behavior?.available===true && !episodeSameRef(packet.behavior.ref,expected.behavior_ref))throw new Error('The matching behavior record has a different exact identity.');
  app.episodePacket=packet;app.episodeExpected=expected;app.episodeQuestion=`Which competing explanation for “${candidate.title}” can a bounded experiment distinguish, and what observable outcome would falsify it?`;
  if(document.getElementById('evidence-dialog').open)document.getElementById('evidence-dialog').close();
  app.view='episode';await render();main.scrollIntoView({block:'start',behavior:'auto'});
}
async function episode() {
  const heading=header('ONE SELECTED EPISODE','From an anomaly to an experiment question.','Keep the original comparison, recorded measurements and rival explanations together.');
  if(!app.episodePacket)return heading+empty('Select an episode first','Open a graph lead from Observatory or a matching behavior from the library. Its exact selected-lead and temporal audits must be saved.','observatory');
  return heading+EpisodeWorkspace.render(app.episodePacket,app.episodeExpected,app.episodeQuestion);
}

