  const metrics = `<div class="metrics-row">${metric('Evidence imports',number(all('dataset').length),'Bounded windows with provenance')}${metric('Behavior candidates',number(all('behavior').length),'Versioned, skeptically reviewed')}${metric('Controlled experiments',number(all('experiment').length + all('network_experiment').length + all('complementary_experiment').length + all('resource_experiment').length + all('timed_resource_experiment').length + all('revision_relay_experiment').length),'Whole swarm = one unit')}${metric('Theory entries',number(all('theory').length),'Hypotheses remain revisable')}</div>`;
  const steps = ['Import','Observe','Discover','Design','Experiment','Evaluate','Theorize'].map((step,i) => `${i ? '<span class="loop-arrow">→</span>' : ''}<div class="loop-step"><span>0${i+1}</span>${step}</div>`).join('');
  const lead = `<section class="panel lead-panel"><div class="panel-body"><span class="eyebrow">ONE RESEARCH LOOP</span><h2>From swarm traces to testable explanations.</h2><p class="section-caption">Inspect communication, investigate unusual episodes, and test a private context intervention in a fresh agent society. Every claim stays linked to its evidence.</p><div class="research-loop">${steps}</div><div class="action-row"><button class="button primary ${app.live ? 'live-button' : ''}" data-action="fixture-workflow">Run ${app.live ? 'live' : 'offline'} fixture workflow <span>↗</span></button><small>The fixture contains synthetic status claims. The wind tunnel checks actual artifact contents.</small></div></div></section>`;
