  const recent = app.state.objects.slice(0,7).map(item => `<div class="object-row"><span class="row-icon">${({dataset:'▤',discovery:'⌘',behavior:'◈',protocol:'⊞',experiment:'↗',theory:'◇'})[item.kind] || '·'}</span><div class="row-main"><h3><button class="button-link" data-open="${esc(item.id)}">${esc(label(item))}</button></h3><p>${esc(human(item.kind))} · version ${number(item.version)} · ${esc(date(item.created))}</p></div>${badge(item.summary.status || item.summary.agent_mode || 'recorded')}</div>`).join('') || '<div class="list-empty">Import a window to begin the evidence registry.</div>';
  const activity = running.length ? `<div class="note orange"><strong>${number(running.length)} job${running.length > 1 ? 's' : ''} active</strong> · ${running.map(job => esc(human(job.payload.stage || job.payload.action || 'research'))).join(', ')}<br><button class="button-link" data-view="audit">Inspect progress and model/tool traces →</button></div>` : '';
  return header('AGENT SOCIETY RESEARCH','A laboratory for agent societies.','Explore what a swarm does, propose why it happens, and test explanations without confusing historical patterns with causal effects.') + metrics + activity + lead + `<div class="grid-two section-gap">${panel('Begin an investigation','Choose a source and a bounded observation window.',form)}${panel('Research registry','Evidence, protocols, results, and evolving explanations.',recent,`<span class="object-count">${number(app.state.objects.length)} objects</span>`)}</div>`;
