function networkSVG(projection) {
  const nodes = projection.nodes || [], edges = projection.edges || [];
  const width=660, height=340, positions={}, radius=Math.min(130,90+nodes.length*5), nodeRadius=nodes.length > 24 ? 8 : nodes.length > 12 ? 12 : 18;
  const spectral = projection.spectral || {};
  const positive = (spectral.modes || []).filter(mode => !mode.null_mode);
  const useSpectral = app.graphLayout === 'spectral' && positive.length >= 2 && spectral.nullity === 1;
  nodes.forEach((node,i) => { if (useSpectral) { const xs=nodes.map(n => positive[0].coefficients[n.id] || 0), ys=nodes.map(n => positive[1].coefficients[n.id] || 0); const maxX=Math.max(...xs.map(Math.abs),.001), maxY=Math.max(...ys.map(Math.abs),.001); positions[node.id]={x:width/2+(positive[0].coefficients[node.id] || 0)/maxX*200,y:height/2+(positive[1].coefficients[node.id] || 0)/maxY*115}; } else { const angle=i*Math.PI*2/Math.max(nodes.length,1)-Math.PI/2; positions[node.id]={x:width/2+Math.cos(angle)*radius,y:height/2+Math.sin(angle)*radius}; } });
  const tone=projection.inferred ? '#b86637' : '#127d86';
  const edgeSVG=edges.map(edge => { const a=positions[edge.source],b=positions[edge.target]; if (!a || !b) return ''; const dx=b.x-a.x,dy=b.y-a.y,length=Math.hypot(dx,dy) || 1; const x1=a.x+dx/length*(nodeRadius+1),y1=a.y+dy/length*(nodeRadius+1),x2=b.x-dx/length*(nodeRadius+5),y2=b.y-dy/length*(nodeRadius+5); const bend=edges.some(other => other.source === edge.target && other.target === edge.source) ? 18 : 0; const cx=(x1+x2)/2-dy/length*bend,cy=(y1+y2)/2+dx/length*bend; const active=!app.selectedNode || edge.source === app.selectedNode || edge.target === app.selectedNode; return `<path d="M${x1.toFixed(1)} ${y1.toFixed(1)} Q${cx.toFixed(1)} ${cy.toFixed(1)} ${x2.toFixed(1)} ${y2.toFixed(1)}" fill="none" stroke="${tone}" opacity="${active ? '.55' : '.13'}" stroke-width="${Math.min(4,1+Math.log1p(edge.weight)).toFixed(2)}" ${projection.inferred ? 'stroke-dasharray="5 4"' : ''} marker-end="url(#arrow)"><title>${esc(edge.weight)} event${edge.weight === 1 ? '' : 's'} · ${esc(edge.evidence_ids.length)} evidence messages</title></path>`; }).join('');
  const nodeSVG=nodes.map(node => { const p=positions[node.id]; const selected=app.selectedNode === node.id; const initial=String(node.name || node.id).split(/\s+/).map(word => word[0]).slice(0,2).join(''); return `<g class="network-node ${selected ? 'selected' : ''}" data-node="${esc(node.id)}" role="button" tabindex="0" aria-label="Inspect ${esc(node.name)}"><title>${esc(node.name)}${node.observed_author_in_scope ? '' : ' · referenced, no authored messages in scope'}</title><circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="${nodeRadius}" fill="${selected ? tone : '#eef6ed'}" stroke="${tone}" stroke-width="1.4"/><text x="${p.x.toFixed(1)}" y="${(p.y+3).toFixed(1)}" text-anchor="middle" style="fill:${selected ? 'white' : tone};font-size:${nodes.length > 24 ? 6 : 9}px">${esc(initial)}</text>${nodes.length <= 14 || selected ? `<text x="${p.x.toFixed(1)}" y="${(p.y+nodeRadius+17).toFixed(1)}" text-anchor="middle">${esc(clip(node.name,22))}</text>` : ''}</g>`; }).join('');
  const caption = !nodes.length ? '<text x="330" y="170" text-anchor="middle" fill="#728185" font-size="12">No agent nodes in this scope.</text>' : !edges.length ? '<text x="330" y="170" text-anchor="middle" fill="#728185" font-size="11">No recorded ties in this channel.</text>' : '';
  return `<svg class="network-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${projection.inferred ? 'Inferred' : 'Observed'} agent relation network"><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0 10 5 0 10Z" fill="${tone}"/></marker></defs>${edgeSVG}${caption}${nodeSVG}</svg>`;
}
function evidenceCards(messages, max=8) { return messages.slice(0,max).map(message => `<article class="evidence-item"><div class="evidence-meta"><strong>${esc(message.agent_name || message.speaker_id)}</strong><span>${esc(utc(message.timestamp || message.created_at))}</span></div><p class="evidence-text">${esc(clip(message.content,330))}</p><button class="button-link mono" data-evidence="${esc(message.id)}">${esc(shortId(message.id))} · inspect full message ↗</button></article>`).join('') || '<div class="list-empty">Select a node or an incident to inspect its source evidence.</div>'; }
function selector(kind, action='') { return `<div class="selector-bar"><label for="select-${esc(kind)}">${esc(human(kind))} window</label><select class="control" id="select-${esc(kind)}" data-select="${esc(kind)}">${options(kind,selected(kind))}</select>${action}</div>`; }
function spectralObservablePanel(projection) {
  if (!projection?.observable_signals) return '';
  const summary=typeof SpectralSignalView==='object' ? SpectralSignalView.render(projection,{signalId:app.spectralSignal}) : '';
  return `<div class="note">These ratios count explicit language hits per authored message. Label calibration and common source context remain unresolved. Missing author observations remain unavailable; graph-signal energy does not identify a latent trait or a causal mechanism.</div>${summary}${raw(projection.observable_signals,'Observable language signals on this graph · missing author data stays unavailable')}`;
}
async function observatoryMain() {
  if (app.pendingDataset) {
    const matching=all('discovery').find(item => item.summary.dataset_id === app.pendingDataset);
    if (matching) { app.selected.discovery=matching.id; app.pendingDataset=null; }
    else {
      const imported=await object(app.pendingDataset), dataset=imported.payload;
      app.selected.dataset=imported.id;
      return header('IMPORTED EVIDENCE','The evidence window is ready.','Build its observability graph and signals before investigating behavior.') + `<div class="metrics-row">${metric('Retained messages',number(dataset.messages.length),'Chronological scoped records')}${metric('Source rows scanned',number(dataset.diagnostics?.chat?.rows_scanned),'Source-order independent selection')}${metric('Agent metadata',number(dataset.agents.length),'Roster records, not concurrent participants')}${metric('Selected goals',number(dataset.goals.length),'Available local metadata')}</div>` + panel('Inspect the import',dataset.source,`<p class="source-scope">${esc(utc(dataset.scope?.start))} → ${esc(utc(dataset.scope?.end_exclusive))}<br>${dataset.diagnostics?.chat?.truncated ? 'The retained scope is truncated.' : 'All matched rows retained.'}</p><div class="action-row"><button class="button primary" data-action="observe" data-id="${esc(imported.id)}">Observe this window</button><button class="button" data-existing-observatory>Open previous observations</button></div><div class="detail-section"><h3>Sample source messages</h3>${evidenceCards(dataset.messages,5)}</div>${raw(dataset.diagnostics,'Import diagnostics')}`);
    }
  }
  const discoveryId=selected('discovery');
  const datasetId=selected('dataset');
  if (!discoveryId) { const extra = datasetId ? `<div class="action-row"><button class="button primary" data-action="observe" data-id="${esc(datasetId)}">Observe latest import</button></div>` : ''; return header('BEHAVIORAL OBSERVABILITY','Look at the society, not just the calls.','Typed relations and narrow observable signals keep interpretation close to the evidence.') + empty('No observed window yet','Import a bounded window, then build its evidence graph and behavioral signals.') + extra; }
  const observed=await object(discoveryId), data=observed.payload;
  const dataset=(await object(data.dataset_id,data.dataset_ref?.version)).payload;
  app.selected.dataset=data.dataset_id;
  const projections=data.network?.projections || {};
  const projection=projections[app.projection] || {nodes:[],edges:[],metrics:{graph:{},nodes:[]},spectral:{}};
  if (app.selectedNode && !projection.nodes.some(node => node.id === app.selectedNode)) app.selectedNode=null;
  const graph=projection.metrics?.graph || {};
  const signalCounts={}; (data.signals || []).forEach(signal => (signal.labels || []).forEach(name => signalCounts[name]=(signalCounts[name] || 0)+1));
  const maximum=Math.max(...Object.values(signalCounts),1);
  const signals=Object.entries(signalCounts).sort((a,b) => b[1]-a[1]).map(([name,count]) => `<div class="signal-bar"><label>${esc(human(name))}</label><div class="bar-track"><div class="bar-fill" style="width:${(count/maximum*100).toFixed(1)}%"></div></div><strong>${number(count)}</strong></div>`).join('') || '<p class="soft-text">No predefined signal was detected in this window.</p>';
  const channelOptions=Object.entries({observed_mentions:'Observed · named mentions',observed_replies:'Observed · recorded replies',inferred_proximity:'Inferred · temporal proximity',inferred_lexical:'Inferred · lexical recurrence'}).map(([id,text]) => `<option value="${id}" ${app.projection === id ? 'selected' : ''}>${text}</option>`).join('');
  const spectralFallback=app.graphLayout === 'spectral' && ((projection.spectral?.modes || []).filter(mode => !mode.null_mode).length < 2 || projection.spectral?.nullity !== 1);
  const graphPanel=`<section class="panel graph-panel"><div class="panel-heading"><div><h2>Communication structure</h2><p>Directed, scope-specific relations.</p></div><div class="graph-toolbar"><select class="control" id="projection" aria-label="Network relation channel">${channelOptions}</select><select class="control" id="graph-layout" aria-label="Graph layout"><option value="radial" ${app.graphLayout === 'radial' ? 'selected' : ''}>Radial layout</option><option value="spectral" ${app.graphLayout === 'spectral' ? 'selected' : ''}>Spectral layout</option></select></div></div>${networkSVG(projection)}<div class="graph-description">${esc(projection.description || 'No network analysis attached to this object.')}${spectralFallback ? '<br>Spectral axes are unavailable for this disconnected or low-rank graph; radial layout shown.' : ''}</div><div class="graph-legend"><span><i class="legend-line"></i>Recorded relation</span><span><i class="legend-line inferred"></i>Inferred candidate relation</span><span>Click a node for evidence</span></div></section>`;
  const spectrum=projection.spectral || {};
  const spectralBody=`<p class="section-caption">${spectrum.available ? 'Normalized graph Laplacian on explicitly symmetrized ties. Direction stays intact in the other metrics.' : spectrum.reason || 'Spectral analysis is not available.'}</p><div class="spectral-info"><div>NULL MODES<strong>${number(spectrum.nullity)}</strong>Components and isolates contribute.</div><div>SECOND EIGENVALUE<strong>${number(spectrum.algebraic_connectivity,3)}</strong>Zero for disconnected graphs.</div></div><div class="note">Graph basis only. A manifold Laplace–Beltrami interpretation is unestablished. Repeated eigenspaces have non-unique coordinates.</div>${raw({operator:spectrum.formula,eigenvalues:spectrum.eigenvalues,repeated_eigenspaces:spectrum.repeated_eigenspaces,warnings:spectrum.warnings},'Eigenvalues, operator, and limitations')}${spectralObservablePanel(projection)}`;
  const edgeIds=new Set((projection.edges || []).filter(edge => !app.selectedNode || edge.source === app.selectedNode || edge.target === app.selectedNode).flatMap(edge => edge.evidence_ids));
  const sources=dataset.messages.filter(message => edgeIds.has(message.id));
  const sourceTitle=app.selectedNode ? `${projection.nodes.find(node => node.id === app.selectedNode)?.name || 'Selected agent'} · evidence` : 'Relation evidence';
  const candidates=(data.candidates || []).slice(0,12).map(candidate => `<article class="candidate-card">${badge(candidate.screening_regime ? 'Exploratory graph lead' : 'Screening candidate')} ${candidate.right_censored ? badge('Right censored','orange') : ''}<h3>${esc(candidate.title)}</h3><p>${esc(candidate.description)}</p><div class="candidate-footer"><span>${number(candidate.evidence_ids?.length)} source messages · novelty unestablished</span><button class="button-link" data-case="${esc(candidate.id)}">Inspect →</button></div></article>`).join('') || '<p class="soft-text">No screening motif matched. Absence of a signal is not proof of absent behavior.</p>';
  const candidatePanel=panel('Episodes worth investigating','Prespecified screening motifs; source adjudication comes before a behavioral claim.',`<div class="candidate-grid">${candidates}</div>`, `<button class="button small ${app.live ? 'live-button' : ''}" data-action="investigate" data-id="${esc(discoveryId)}" ${(data.candidates || []).length ? '' : 'disabled'}>Investigate ${app.live ? 'with agents' : 'offline'}</button>`);
  const rows=dataset.messages.slice(app.messagePage*10,app.messagePage*10+10);
  const messageTable=`<div class="table-wrap"><table><thead><tr><th>UTC TIME</th><th>SPEAKER</th><th>MESSAGE</th><th>EVIDENCE</th></tr></thead><tbody>${rows.map(message => `<tr><td class="mono">${esc(utc(message.timestamp))}</td><td>${esc(message.agent_name)}</td><td>${esc(clip(message.content,125))}</td><td><button class="button-link mono" data-evidence="${esc(message.id)}">${esc(shortId(message.id))}</button></td></tr>`).join('')}</tbody></table></div><div class="pager"><button class="button small" data-page="prev" ${app.messagePage === 0 ? 'disabled' : ''}>Previous</button><span>${number(app.messagePage*10+1)}–${number(Math.min((app.messagePage+1)*10,dataset.messages.length))} of ${number(dataset.messages.length)}</span><button class="button small" data-page="next" ${(app.messagePage+1)*10 >= dataset.messages.length ? 'disabled' : ''}>Next</button></div>`;
  return header('BEHAVIORAL OBSERVATORY','Inspect the swarm’s social structure.','Separate observed relations from inferred interaction. Every screening motif can be traced back to its messages.') + selector('discovery',`<button class="button small" data-action="observe" data-id="${esc(datasetId || data.dataset_id)}">Observe selected import</button>`) + measurementPanel(data, datasetId || data.dataset_id) + graphDiscoveryPanel(data, discoveryId, observed) + `<div class="metrics-row">${metric('Agent nodes',number(graph.node_count),'Authored or referenced in scope')}${metric('Directed ties',number(graph.directed_edge_count),human(app.projection))}${metric('Relation events',number(graph.interaction_count),'Events with source references')}${metric('Reciprocity',percent(graph.binary_reciprocity),'Structural, not causal')}</div><div class="observatory-grid"><div>${graphPanel}${panel('Evidence inspection','Source messages behind the selected relations.',`<div class="evidence-list">${evidenceCards(sources,8)}</div>`,app.selectedNode ? '<button class="button-link" data-clear-node>Clear selection</button>' : '')}</div><div>${panel('Observable signals','Narrow labels, not inferred mental states.',signals + `<div class="note cyan">${esc(data.detector_version || '')}<br>Regex screening is a measurement instrument that needs adjudication.</div>`)}${panel('Spectral structure','Explore graph modes without a geometric overclaim.',spectralBody)}</div></div><div class="section-gap">${candidatePanel}</div><div class="section-gap">${panel('Dataset window','Chronological messages with exact source provenance.',`<div class="source-scope">${esc(dataset.source)}<br>${esc(utc(dataset.scope?.start))} → ${esc(utc(dataset.scope?.end_exclusive))}<br>${number(dataset.diagnostics?.chat?.rows_scanned)} source rows scanned · ${dataset.diagnostics?.chat?.truncated ? 'retained scope truncated' : 'all matched rows retained'}</div><div class="page-divider"></div>${messageTable}${raw(dataset.diagnostics,'Import diagnostics')}`)}</div><div class="section-gap">${panel('Network reference comparison','Conditional author-label shuffles preserve room/hour activity.',raw(data.network?.null_reference || {},'Inspect null-model assumptions and exploratory comparisons') + raw(projection.metrics || {},'Directed node metrics and exposure proxies'))}</div>`;
}

function replicationEvidencePanel(payload) {
  const summary=payload.replication_summary, registry=payload.directional_evidence_registry, entries=payload.quantitative_evidence || [];
  if (!summary && !registry && !entries.length && !(payload.replication_ids || []).length) return '';
  const linked=(ids) => (ids || []).map(id => `<button class="button-link mono" data-open="${esc(id)}">${esc(shortId(id))} ↗</button>`).join(' ') || '<span class="soft-text">None recorded</span>';
  const classes=[['supporting_positive_contrast','Positive registered contrasts'],['conflicting_negative_contrast','Negative registered contrasts'],['inconclusive_contrast','Inconclusive contrasts'],['scripted_infrastructure_only','Scripted infrastructure only']];
  const rows=entries.map(entry => { const q=entry.quantitative_summary || {}, ref=entry.experiment || {}; const counts=Object.entries(q.arms || {}).map(([arm,value]) => `${({baseline:'Baseline',placebo:'Neutral',evidence_thought:'Reminder'})[arm] || human(arm)} ${value.correct}/${value.total}`).join(' · '); return `<tr><td><button class="button-link mono" data-open="${esc(ref.id)}">${esc(shortId(ref.id))} ↗</button><small>Recorded version ${number(ref.version)} · ${esc(entry.agent_mode)}</small></td><td>${esc(counts)}</td><td>${esc(statusNames[q.primary_conclusion] || human(q.primary_conclusion))}<small>${pp(q.difference)} · 95% interval ${pp(q.ci95?.[0])} to ${pp(q.ci95?.[1])}</small></td></tr>`; }).join('');
  return `<div class="detail-section replication-evidence"><h3>Seed replication and directional evidence</h3><div class="note cyan"><strong>${number(summary?.attempt_count || (payload.replication_ids || []).length)} recorded replication attempt${Number(summary?.attempt_count || (payload.replication_ids || []).length) === 1 ? '' : 's'}</strong><br>${esc(human(summary?.latest_attempt_status || payload.replication_status))}. This status describes a test in a fixed task and model; it does not establish the broader theory.<br>Pooled analysis: ${esc(human(summary?.pooled_analysis || 'not_computed'))}.</div>${registry ? `<p class="section-caption">${esc(registry.target)}</p><p class="field-help">${esc(registry.interpretation)}</p><dl class="key-value directional-registry">${classes.map(([key,title]) => `<dt>${esc(title)}</dt><dd>${linked(registry[key])}</dd>`).join('')}</dl>` : ''}${rows ? `<div class="table-wrap"><table><caption>Separate study results · each team is one unit</caption><thead><tr><th scope="col">EXECUTED STUDY</th><th scope="col">CORRECT / TEAMS</th><th scope="col">REGISTERED CONTRAST</th></tr></thead><tbody>${rows}</tbody></table></div>` : ''}<div class="action-row">${linked(payload.replication_ids)}</div><p class="field-help">Historical mechanism, mediation, and transfer remain separately evaluated. Positive and inconclusive studies remain visible together.</p>${raw({replication_summary:summary,directional_evidence_registry:registry,quantitative_evidence:entries},'Recorded replication and result provenance')}</div>`;
}
function claimAuditPanel(record) {
  if (!record) return '';
  const payload=record.payload || {}, audited=payload.audit || {}, rows=audited.claims || [];
  const claims=Array.isArray(payload.claims) ? payload.claims : payload.claims?.claims || [];
  const supported=rows.filter(row => row.status === 'supported' && typeof row.approved_fact_text === 'string');
  const discrepancies=rows.filter(row => ['mismatch','unavailable','invalid'].includes(row.status));
  const unverified=rows.filter(row => row.status === 'unverified');
  const issues=audited.ledger_issues || [];
  const target=payload.experiment_id || payload.result_ref?.id;
  const facts=supported.map(row => `<li><p>${esc(row.approved_fact_text)}</p><small class="mono">${esc(row.fact_id)}</small></li>`).join('');
  const rejected=discrepancies.map(row => `<tr><td>${esc(row.id)}</td><td>${badge(row.status,'orange')}</td><td>${esc(row.reason)}${row.actual !== undefined ? `<small>Recorded value: ${esc(JSON.stringify(row.actual))}</small>` : ''}</td></tr>`).join('');
  const statements=claims.filter(claim => typeof claim.statement === 'string' && claim.statement.trim());
  const prose=statements.map(claim => `<article class="unverified-statement"><h4>${esc(claim.id)} · ${esc(human(claim.scope))}</h4><p>${esc(claim.statement)}</p></article>`).join('') || '<p>No attached prose was submitted. This does not verify other commentary about the result.</p>';
  return `<div class="detail-section claim-audit"><div class="detail-head"><div><h3>Machine-checked result facts</h3><p class="mono">${esc(record.id)} · version ${number(record.version)} · ${esc(payload.agent_mode)}</p></div>${badge(discrepancies.length || issues.length ? 'Needs review' : 'Finite facts checked',discrepancies.length || issues.length ? 'orange' : 'cyan')}</div><p class="section-caption">${number(supported.length)} typed assertions checked · ${number(discrepancies.length)} mismatches or unavailable assertions · ${number(unverified.length)} unverified claims.</p><div class="note">Only the code-generated fact text below is checked against this report. Attached model sentences and proposed mechanisms remain unverified. A sample contrast does not establish historical causation or transfer.</div>${facts ? `<ul class="checked-facts">${facts}</ul>` : '<div class="list-empty">No supported executable fact text is recorded.</div>'}${rejected ? `<h4 class="subheading">Assertions requiring review</h4><div class="table-wrap"><table><thead><tr><th scope="col">CLAIM</th><th scope="col">STATUS</th><th scope="col">CHECK RESULT</th></tr></thead><tbody>${rejected}</tbody></table></div>` : ''}${issues.length ? `<div class="note orange">The underlying ledger reports data or replay issues. Inspect them before interpreting the result.${raw(issues,'Ledger issues')}</div>` : ''}<details class="commentary-detail"><summary>Unverified model statements · ${number(statements.length)} attached</summary><p>${esc(payload.prose_scope || 'Typed fact agreement does not verify the wording, mechanism, or scope of model prose.')}</p>${prose}${raw(claims,'Submitted finite claims and attached statements')}</details><div class="action-row">${target ? `<button class="button small" data-open="${esc(target)}">Open associated result</button>` : ''}<button class="button small" data-history="${esc(record.id)}">Inspect audit versions</button></div><p class="hash">Source fingerprint ${esc(audited.source_fingerprint || payload.fact_packet?.source_fingerprint)}${payload.result_ref?.version ? ` · result version ${number(payload.result_ref.version)}` : ''}</p>${raw(payload.fact_packet || {},'Bounded facts supplied to the evaluator')}${raw(audited,'Typed claim checks and limitations')}</div>`;
}

function artifactRouteScreening(p) {
  const notes={
    shared_artifact_coordination:'Candidate for an artifact study. Check the mechanism and study protocol before execution.',
    requires_new_environment:'Review a different world for this candidate. Another existing authoring family may fit; check its capabilities and mechanism.',
    not_applicable:'No study is proposed for this declined lead.',
  };
  const note=Object.prototype.hasOwnProperty.call(notes,p.experiment_fit) ? notes[p.experiment_fit] : 'No artifact workflow recommendation is available. Review source evidence and required capabilities before choosing a study.';
  return `<div class="detail-section"><h3>Artifact workflow screening</h3><p>${esc(note)}</p><p>${esc(p.fit_reason)}</p><p class="field-help">This recommendation concerns the initial artifact workflow. Environment authoring reviews the available worlds separately.</p></div>`;
}

async function libraryBehaviorSource(p) {
  const unavailable=(status,reason,ref=null)=>({available:false,status,reason,ref,messages:null});
  if (!Object.prototype.hasOwnProperty.call(p,'dataset_id') && !Object.prototype.hasOwnProperty.call(p.source_refs || {},'dataset')) return unavailable('not_declared','No dataset source is declared in this behavior record. Its evidence availability is unknown.');
  let ref;
  try {
    ref=episodeRef(p.source_refs?.dataset);
    if (typeof p.dataset_id !== 'string' || p.dataset_id !== ref.id) throw new Error('Source identity mismatch');
  } catch (_) { return unavailable('invalid_reference','A complete matching dataset reference is missing or invalid. No latest version was substituted.'); }
  let record;
  try { record=await object(ref.id,ref.version); }
  catch (_) { return unavailable('unavailable','The exact saved dataset version could not be loaded. Its source evidence is unavailable in this workspace.',ref); }
  if (record?.kind !== 'dataset' || !episodeSameRef(record,ref) || !Array.isArray(record.payload?.messages)) return unavailable('unavailable','The returned dataset does not match this record\'s exact source reference.',ref);
  const ids=p.evidence_ids;
  if (!Array.isArray(ids) || ids.some(id=>typeof id !== 'string')) return unavailable('unavailable','The behavior\'s cited record IDs are unavailable or invalid.',ref);
  const messages=record.payload.messages,known=new Set(messages.filter(message=>message && typeof message.id==='string').map(message=>message.id));
  if (ids.some(id=>!known.has(id))) return unavailable('unavailable','Some cited records are absent from the exact saved dataset. No substitute evidence was selected.',ref);
  return {available:true,status:'available',reason:null,ref,messages:messages.filter(message=>message && ids.includes(message.id))};
}
function librarySourceEvidence(source) {
  if (source.available) return `<div class="detail-section" data-library-source-status="available"><h3>Source evidence</h3><p>Referenced dataset version ${source.ref.version} is available. Source interpretation remains unverified.</p><div class="evidence-list">${source.messages.length ? evidenceCards(source.messages,8) : '<p>No source record IDs are cited by this behavior.</p>'}</div></div>`;
  return `<div class="detail-section" data-library-source-status="${esc(source.status)}"><h3>Source evidence ${source.status==='not_declared' ? 'unknown' : 'unavailable'}</h3><div class="note orange"><p>${esc(source.reason)}</p><p>The behavior, critique and history remain readable. Artifact design is withheld until the exact source is available.</p></div></div>`;
}

async function library() {
  const kind=app.libraryKind, identity=selected(kind), obj=identity ? await object(identity) : null;
  const list=all(kind);
  const left=`<div class="library-list"><div class="tabs"><button class="tab-button ${kind === 'behavior' ? 'active' : ''}" data-library="behavior">Behaviors <span>${number(all('behavior').length)}</span></button><button class="tab-button ${kind === 'theory' ? 'active' : ''}" data-library="theory">Theories <span>${number(all('theory').length)}</span></button></div>${list.map(item => `<button class="library-item ${item.id === identity ? 'active' : ''}" data-library-id="${esc(item.id)}">${badge(item.summary.status || 'candidate')}<h3>${esc(label(item))}</h3><small>Version ${number(item.version)} · ${esc(date(item.created))}</small></button>`).join('') || '<div class="list-empty">No entries yet. Investigate an observed episode.</div>'}</div>`;
  let right=empty('Knowledge accumulates here','Candidates, critiques, experiment results, and theory revisions share an inspectable history.','observatory');
  if (obj) {
    const p=obj.payload;
    if (kind === 'behavior') {
      const source=await libraryBehaviorSource(p);
      right=panel('Behavior record','A claim with evidence, alternatives, and revision history.',`<div class="detail-head"><div><h2>${esc(p.name)}</h2><p>${esc(obj.id)} · version ${number(obj.version)} · ${esc(p.agent_mode)}</p></div>${badge(p.status)}</div><p class="section-caption">${esc(p.summary)}</p><div class="note ${p.status === 'rejected' ? 'orange' : ''}"><strong>Evidence level:</strong> ${esc(human(p.evidence_level))}<br>${esc(p.causal_support || 'No causal support.')}<br>Novelty: ${esc(human(p.novelty_status))}</div>${replicationEvidencePanel(p)}${measurementReviewPanel(p)}<div class="detail-section"><h3>Operational definition</h3><p>${esc(p.operational_definition)}</p></div><div class="detail-section"><h3>Competing explanations</h3>${bullets(p.alternative_explanations)}</div><div class="detail-section"><h3>Predictions that can be wrong</h3>${bullets(p.falsifiable_predictions)}</div><div class="detail-section"><h3>Independent critique</h3><p>${esc(p.skeptic?.summary)}</p>${bullets(p.skeptic?.unsupported_claims)}<p>${esc(human(p.skeptic?.recommended_status))}</p></div>${librarySourceEvidence(source)}${artifactRouteScreening(p)}<div class="action-row"><button class="button primary" data-design-behavior="${esc(obj.id)}" ${p.status === 'rejected' || p.experiment_fit !== 'shared_artifact_coordination' || !source.available ? 'disabled' : ''}>Design artifact study →</button>${source.available ? episodeButton(p.source_refs?.discovery,p.candidate_id,obj) : ''}<button class="button" data-history="${esc(obj.id)}">Inspect version history</button></div>${raw(p,'Complete behavior record')}`);
    } else {
      right=panel('Theory record','Mechanisms, boundary conditions, and falsifiers stay together.',`<div class="detail-head"><div><h2>${esc(p.title)}</h2><p>${esc(obj.id)} · version ${number(obj.version)}</p></div>${badge(p.status)}</div><div class="note cyan">${esc(human(p.replication_status))} · Generalization ${esc(human(p.generalization))}. Replication records test a bounded task/model contrast and do not establish this theory.</div>${replicationEvidencePanel(p)}<details class="commentary-detail theory-hypothesis"><summary>Candidate statement and proposed mechanism · unverified</summary><h3 class="subheading">Candidate statement</h3><p>${esc(p.statement)}</p><h3 class="subheading">Proposed mechanism</h3><p>${esc(p.mechanism)}</p></details><div class="detail-section"><h3>Predictions</h3>${bullets(p.predictions)}</div><div class="detail-section"><h3>Rival theories</h3>${bullets(p.rival_theories)}</div><div class="detail-section"><h3>Falsifiers</h3>${bullets(p.falsifiers)}</div><div class="detail-section"><h3>Boundary conditions</h3>${bullets(p.boundary_conditions)}</div><div class="detail-section"><h3>Next experiments</h3>${bullets(p.next_experiments)}</div><div class="detail-section"><h3>Linked research</h3>${[...(p.behavior_ids || []),...(p.experiment_ids || [])].map(id => `<p><button class="button-link mono" data-open="${esc(id)}">${esc(id)} ↗</button></p>`).join('')}</div><div class="action-row"><button class="button" data-history="${esc(obj.id)}">Inspect version history</button></div>${raw(p,'Complete theory record')}`);
    }
  }
  return header('BEHAVIOR & THEORY LIBRARY','Keep explanations open to revision.','A candidate is not a discovery. Seed-replication status describes a fixed task and model test. Preserve alternatives, negative results, and falsifiers.') + `<div class="library-grid">${left}<div>${right}</div></div>`;
}

function measurementReviewPanel(p) {
  const records=p.measurement_sensitivity_reviews || [];
  if(!records.length)return '';
  return `<div class="detail-section"><h3>Measurement sensitivity review</h3>${records.map(r=>{
    const ref=r.audit_ref || r.graph_audit_ref;
    const contrasts=r.native_contrasts ? `<dl class="key-value">${Object.entries(r.native_contrasts).map(([key,value])=>`<dt>${esc(human(key))}</dt><dd>${signed(value)}</dd>`).join('')}</dl><p>Candidate minus original comparator; native node-universe policy. Fixed-pair values remain in the exact review.</p>` : '';
    const findings=r.findings?.length ? bullets(r.findings) : '';
    const limitations=r.limitations?.length ? bullets(r.limitations) : '';
    const interpretation=r.interpretation ? `<p>${esc(r.interpretation)}</p>` : '';
    return `<div class="note orange"><p>${esc(r.scope)}</p>${findings}${contrasts}${limitations}${interpretation}${ref ? `<button class="button small" data-open="${esc(ref.id)}" data-open-version="${number(ref.version)}">${r.audit_ref ? 'Inspect pinned selected-window audit' : 'Inspect pinned graph diagnostic'}</button>` : ''}${raw(r,'Review mode and exact diagnostic version')}</div>`;
  }).join('')}</div>`;
}

