async function observatory() {
  const body=await observatoryMain();
  if (app.pendingDataset || !selected('discovery')) return body;
  const discovery=await object(selected('discovery')), ref=discovery?.payload?.dataset_ref;
  if (!ref) return body;
  const records=await Promise.all(all('measurement_audit').filter(o=>o.summary.dataset_id===ref.id).map(o=>object(o.id)));
  const audit=records.find(o=>o.payload.dataset_ref?.version===ref.version && o.payload.agent_authored_only===true);
  const eligible=await Promise.all(all('name_eligibility_audit').filter(o=>o.summary.dataset_id===ref.id).map(o=>object(o.id)));
  const shortAudit=eligible.find(o=>o.payload.dataset_ref?.version===ref.version && o.payload.agent_authored_only===true);
  const graphs=await Promise.all(all('graph_measurement_audit').filter(o=>o.summary.dataset_id===ref.id).map(o=>object(o.id)));
  const graphAudit=graphs.find(o=>o.payload.eligibility_audit_ref?.id===shortAudit?.id && o.payload.eligibility_audit_ref?.version===shortAudit?.version && o.payload.eligibility_audit_ref?.hash===shortAudit?.hash);
  const leads=await Promise.all(all('selected_lead_audit').filter(o=>o.summary.dataset_id===ref.id).map(o=>object(o.id)));
  const leadAudit=leads.find(o=>o.payload.discovery_ref?.id===discovery.id && o.payload.discovery_ref?.version===discovery.version && o.payload.discovery_ref?.hash===discovery.hash);
  const temporal=leadAudit ? await Promise.all(all('temporal_path_audit').filter(o=>o.summary.dataset_id===ref.id).map(o=>object(o.id))) : [];
  const temporalAudit=temporal.find(o=>o.payload.selected_audit_ref?.id===leadAudit.id && o.payload.selected_audit_ref?.version===leadAudit.version && o.payload.selected_audit_ref?.hash===leadAudit.hash);
  const references=temporalAudit ? await Promise.all(all('temporal_timestamp_reference').map(o=>object(o.id))) : [];
  const reference=references.find(o=>o.payload.temporal_audit_ref?.id===temporalAudit.id && o.payload.temporal_audit_ref?.version===temporalAudit.version && o.payload.temporal_audit_ref?.hash===temporalAudit.hash);
  const referenceProofs=reference ? await Promise.all(all('verification').map(o=>object(o.id))) : [];
  const referenceProof=referenceProofs.find(o=>exactTemporalReferenceProof(reference,o));
  return body+`<div class="section-gap">${mentionAuditPanel(audit,ref.id,ref.version)}</div><div class="section-gap">${eligibilityAuditPanel(shortAudit,ref.id,ref.version,graphAudit)}</div><div class="section-gap">${selectedLeadAuditPanel(leadAudit,discovery)}</div>${leadAudit ? `<div class="section-gap">${temporalAuditPanel(temporalAudit,leadAudit)}</div>` : ''}${temporalAudit ? `<div class="section-gap">${temporalReferencePanel(reference,temporalAudit,referenceProof)}</div>` : ''}`;
}

function temporalAuditPanel(record,selectedAudit=null) {
  const p=record?.payload;
  const rows=p ? Object.entries(p.windows || {}).flatMap(([id,window])=>Object.entries(window.variants || {}).map(([variant,v])=>`<tr><td>${esc(utc(window.scope.start))}<br>${esc(human(variant))}<br><small>${esc(clip(id,21))}</small></td><td>${v.available ? number(v.event_count) : 'Unavailable'}</td><td>${v.available ? `${number(v.static?.reachable_pair_count)} → ${number(v.strict_temporal?.reachable_pair_count)}<br><small>${number(v.static_only_pair_count)} static-only</small>` : '—'}</td><td>${v.available ? `${number(v.static?.node_removal?.maximum_loss_fraction,3)} → ${number(v.strict_temporal?.node_removal?.maximum_loss_fraction,3)}` : '—'}</td></tr>`)).join('') : '';
  const controls=selectedAudit ? `<button class="button" data-action="audit-temporal-paths" data-id="${esc(selectedAudit.id)}" data-version="${number(selectedAudit.version)}">Audit temporal paths · no model calls</button>` : '';
  const results=p ? `<p>${number(Object.keys(p.windows || {}).length)} original windows · ${p.source_audit_replay_passed ? 'source audit independently reproduced' : 'source replay unverified'} · no rematching.</p><div class="table-wrap"><table><thead><tr><th>WINDOW / INSTRUMENT</th><th>EVENTS</th><th>PAIRS<br>STATIC → TEMPORAL</th><th>BRIDGE LOSS<br>STATIC → TEMPORAL</th></tr></thead><tbody>${rows}</tbody></table></div><p>Each window uses one node universe across its requested instruments. It can differ from the earlier native or pair-common graph universe. Bridge loss excludes pairs involving the removed agent as an endpoint; undefined fractions remain unavailable.</p><div class="action-row"><button class="button" data-action="replay-temporal-paths" data-id="${esc(record.id)}" data-version="${number(record.version)}">Replay temporal source audit</button></div>${Object.entries(p.windows || {}).map(([id,window])=>raw(window,`Original events and timestamped path witnesses · ${id}`)).join('')}${raw(p.definitions,'Temporal-path definitions')}${raw(p.bounds,'Declared work and output bounds')}${raw(record,'Exact temporal audit identity, source pins and limitations')}` : '<p>No temporal path audit for this exact selected-window instrument yet.</p>';
  return panel('Time-respecting reference paths','Check message order before interpreting a static bridge.',`<p>A path must stay in one room and use strictly increasing timestamps. Equal-time events cannot create a multi-step path. The direction is author to named agent: these are reference opportunities, with delivery, reading and influence unresolved.</p><div class="action-row">${controls}</div>${results}`);
}
function exactTemporalReferenceProof(record,proof) {
  const p=proof?.payload || {}, ref=p.reference_ref || {};
  return proof?.kind==='verification' && p.result_kind==='temporal_timestamp_reference' && ref.id===record?.id && ref.version===record?.version && ref.hash===record?.hash && p.passed===true && p.model_calls===0 && p.source_replay_attempted===true && p.source_replay_completed===true;
}
function temporalReferencePanel(record,temporalAudit=null,proof=null) {
  const p=record?.payload || {}, r=p.timestamp_reference || {}, checked=exactTemporalReferenceProof(record,proof);
  const labels={reachable_pair_count:'Strict temporal reachable pairs',maximum_loss_fraction:'Maximum endpoint-excluded deletion loss'};
  const value=x=>x===null || x===undefined ? 'Undefined' : number(x,4);
  const rows=Object.entries(r.windows || {}).flatMap(([wid,w])=>Object.entries(w.variants || {}).flatMap(([name,cell])=>{
    if(cell.available!==true || !cell.reference)return [`<tr><td>${esc(wid)}<br>${esc(human(name))}</td><td colspan="5">${esc(human(cell.status))}: ${esc(cell.reason || 'Unavailable; no partial ranks')}</td></tr>`];
    return Object.entries(labels).map(([metric,label])=>{
      const summary=cell.reference.metrics?.[metric] || {}, env=summary.envelope, ranks=summary.rank_counts;
      const envelope=env ? ['minimum','q25','median','q75','maximum'].map(k=>value(env[k])).join(' / ') : 'Undefined';
      return `<tr><td>${esc(clip(wid,23))}<br><small>${esc(human(name))}</small></td><td>${esc(label)}</td><td>${esc(value(cell.observed?.[metric]))}</td><td>${esc(envelope)}</td><td>${ranks ? `${number(ranks.less_than_observed)} / ${number(ranks.equal_to_observed)} / ${number(ranks.greater_than_observed)}` : 'Undefined'}</td><td>${number(summary.defined_draws)} / ${number(summary.undefined_draws)}</td></tr>`;
    });
  })).join('');
  const controls=temporalAudit ? `<label class="field"><span>Deterministic reference seed</span><input type="number" min="0" max="9007199254740991" step="1" data-field="temporalRefSeed" value="${esc(app.temporalRefSeed)}"></label><label class="field"><span>Requested draws per cell · 1–256</span><input type="number" min="1" max="256" step="1" data-field="temporalRefDraws" value="${esc(app.temporalRefDraws)}"></label><button class="button" data-action="audit-temporal-reference" data-id="${esc(temporalAudit.id)}" data-version="${number(temporalAudit.version)}">Create bounded timestamp reference · zero model calls</button><p class="field-help">Exact temporal source version ${number(temporalAudit.version)}. A ten-million work ceiling may leave all requested cells uncomputed; unknown cells carry no partial ranks.</p>` : '<p>Select or create an exact temporal path audit before generating a timestamp reference.</p>';
  const refs=Object.entries(p.source_refs || {}).map(([role,ref])=>`<li>${esc(human(role))}: <button class="button-link mono" data-open="${esc(ref.id)}" data-open-version="${number(ref.version)}">${esc(ref.id)} · v${number(ref.version)} ↗</button><br><span class="hash">${esc(ref.hash)}</span></li>`).join('');
  const result=record ? `<p class="mono">${esc(record.id)} · v${number(record.version)} · ${esc(record.hash)}</p>${badge(r.status)}<div class="note ${checked ? 'cyan' : 'orange'}">${checked ? 'Recorded pinned-source replay: passed for this exact reference version/hash.' : 'No passing source replay selected for this exact version/hash. The table is recorded descriptive output.'}</div><div class="table-wrap"><table><thead><tr><th>ORIGINAL WINDOW / INSTRUMENT</th><th>METRIC</th><th>ORIGINAL</th><th>REFERENCE MIN / Q25 / MEDIAN / Q75 / MAX</th><th>DRAWS LESS / EQUAL / GREATER</th><th>DEFINED / UNDEFINED DRAWS</th></tr></thead><tbody>${rows || '<tr><td colspan="6">No reference cells recorded.</td></tr>'}</tbody></table></div><p>Undefined deletion denominators stay undefined. Rank counts can be tied or degenerate; a constant metric does not prove identical assignments. Maximizing nodes and eligible-pair denominators may change across assignments.</p><div class="action-row"><button class="button" data-action="replay-temporal-reference" data-id="${esc(record.id)}" data-version="${number(record.version)}">Fresh pinned-source reference replay · zero model calls</button></div><h3 class="subheading">Exact upstream sources</h3><ul>${refs}</ul>${raw(r.configuration,'Message-group conditioning and excluded no-edge messages')}${raw(r.bounds,'Aggregate computation and output limits')}${raw(r.windows || {},'Original event pins, fixed static graphs and synthetic assignment fingerprints')}${raw(record,'Exact conditional reference, code pins and descriptive limits')}${checked ? raw(proof,'Exact source-bound replay identity') : ''}` : '<p>No timestamp reference for this exact source yet.</p>';
  return panel('Conditional timestamp reference','Compare original counts with a descriptive scheduling reference.',`<div class="note">Timestamps are permuted among edge-bearing source-message groups within each original room/window/instrument. All accepted target edges from one message move together. The static graph and message-time multiset/ties stay fixed; edge-time multiplicities can change with different target group sizes.</div><p>Envelopes are not confidence intervals. Rank counts are not p-values or significance tests. Scheduling, roles, tasks and bursts are ordinary rivals; exchangeability is unestablished. These are the same selected windows, not independent replication, observed recipient exposure or causal effects. No graph or library status is changed.</p><div class="form-grid">${controls}</div>${result}`);
}
async function temporalReferenceAuditSection() {
  const id=selected('temporal_timestamp_reference'), record=await object(id);
  const ref=record?.payload?.temporal_audit_ref, temporal=ref ? await object(ref.id,ref.version) : await object(selected('temporal_path_audit'));
  const proofs=record ? await Promise.all(all('verification').map(item=>object(item.id))) : [];
  const proof=proofs.find(item=>exactTemporalReferenceProof(record,item));
  return `<div class="section-gap">${record ? selector('temporal_timestamp_reference') : ''}${temporalReferencePanel(record,temporal,proof)}</div>`;
}
