  const result=s ? `<dl class="key-value"><dt>Baseline exact pairs</dt><dd>${number(s.baseline_exact_event_count)}</dd><dt>Explicit short-name candidates</dt><dd>${number(s.short_candidate_exact_event_count)}</dd><dt>Expanded exact candidates</dt><dd>${number(s.expanded_exact_candidate_event_count)}</dd><dt>Expanded Unicode candidates</dt><dd>${number(u?.expanded_shadow_candidate_event_count)}</dd><dt>Ambiguous exact targets</dt><dd>${number(s.ambiguous_exact_event_count)}</dd></dl><p>Requested names: ${esc(p.requested_names.join(', ') || '(empty)')}. Expanded values are candidate scans, not graph counts. Exact spans use original text; shadow spans use normalized text.</p>${raw(p.allowlist_resolution,'Explicit original-name roster resolution')}${raw(p.short_name_exact_events,'Short-name candidate matches and original spans')}${raw(p,'Full eligibility sensitivity, source pins and limitations')}` : '<p>No explicit short-name sensitivity for this source version yet.</p>';
