  document.getElementById('dialog-body').innerHTML=`<h2>${esc(runId)}</h2><p>${esc(human(run.context))} · ${percent(run.outcomes.task_completion_fraction)} executed completion</p><div class="note orange">Researcher-only trace. The hidden release round and full schedule are exposed after execution for audit; subjects received current resource state and their own task progress.</div><div class="table-wrap"><table><thead><tr><th>STEP</th><th>SUBJECT</th><th>ACTION</th><th>EXECUTED RESULT</th></tr></thead><tbody>${rows}</tbody></table></div>${raw(run.outcomes,'Task counters and post-treatment waiting metrics')}${raw(run.initial_state,'Researcher-only initial resource state and schedule')}${raw(run.turns,'Exact subject packets, actions and receipts')}${raw(run.final_state,'Executed final state and unverified messages')}`;
