  const capabilities=`<p class="section-caption">${esc(catalog.ontology_policy || 'An expandable inventory of implemented environments, not a closed ontology of swarm behavior.')}</p>${catalogError ? `<div class="note orange">Capability catalog unavailable: ${esc(catalogError)}</div>` : ''}<div class="environment-template-grid">${templates || '<p>No template inventory returned.</p>'}</div>${raw(catalog.capability_definitions || {},'Exact capability identifiers and meanings')}${raw(catalog.unsupported_examples || [],'Explicit unsupported examples · request other capabilities freely')}${raw(packet.builder_schema || {},'Builder output schema')}${raw(packet.reviewer_schema || {},'Methodologist review schema')}`;
  const blueprintId=selected('environment_blueprint'), blueprint=await object(blueprintId);
  const registrationPreview=await loadBlueprintRegistrationPreview(blueprint);
  const attempts=await Promise.all(all('environment_construction_attempt').slice(0,20).map(item=>object(item.id)));
  const cards=attempts.map(record=>{ const p=record.payload || {}; return `<article class="job-card"><h3>${esc(record.id)} · version ${number(record.version)}</h3>${badge(p.status,p.status==='failed' ? 'orange' : '')}<p>${esc(p.research_question)}</p>${p.failed_phase ? `<p>Failed procedure phase: ${esc(p.failed_phase)}</p>` : ''}${p.error ? `<p class="error-text">${esc(p.error)}</p>` : ''}<div class="note">This attempt records world-building procedure, not a behavioral result from subject agents.</div><div class="action-row">${p.blueprint_id ? `<button class="button small" data-open="${esc(p.blueprint_id)}">Inspect blueprint</button>` : ''}<button class="button small" data-history="${esc(record.id)}">Inspect attempt history</button>${p.research_job_id ? `<button class="button small" data-trace="${esc(p.research_job_id)}">Inspect builder/reviewer trace</button>` : ''}</div>${raw(p,'Archived request, generated proposal, compilation and failure detail')}</article>`; }).join('');
