  const rows=cells.map(cell=>{const d=cell.decomposition,scope=d?.scope || cell.preflight?.scope || {},energies=d?.available===true ? d.energies : null,signal=energies?.signal?.squared_norm,energy=key=>hodgeDisplay(energies?.[key]?.squared_norm,signal),fraction=key=>hodgeDisplay(energies?.[key]?.fraction_of_signal),balanced=Array.isArray(cell.edge_source_pins) ? cell.edge_source_pins.filter(edge=>edge.net_reference_events===0).length : null,s=cell.source_scope || {},unavailable=d?.available===true ? '' : ` · unavailable: ${esc(cell.source_unavailable_reason || d?.reason || (p.unknown_reasons || []).join(', ') || 'not computed')}`;return `<tr><td>${esc(s.start || cell.window_id)} → ${esc(s.end_exclusive || 'unknown end')}${unavailable}</td><td>${esc(human(cell.variant))}</td><td>${count(scope.node_count)} / ${count(scope.edge_count)} / ${count(balanced)}</td><td>${count(cell.source_reference_event_count)}</td><td>${energy('signal')}</td><td>${energy('gradient')}</td><td>${energy('circulation')}</td><td>${fraction('gradient')} / ${fraction('circulation')}</td></tr>`;}).join('');
  const parent=p.temporal_audit_ref,parentLink=actorEventRefValid(parent) ? `<button class="button-link mono" data-open="${esc(parent.id)}" data-open-version="${parent.version}">${esc(parent.id)} · v${parent.version} ↗</button>` : 'Exact temporal parent unavailable';
  const compact=cells.map(cell=>({...cell,decomposition:cell.decomposition ? Object.fromEntries(['available','status','reason','scope','canonical_input','energies','backend','configuration','diagnostics','input_fingerprint'].map(key=>[key,cell.decomposition[key]])) : null}));
  return panel('Static edge-count algebra','Gradient fit and circulation residual of a declared net reference-count signal.',`<p class="mono">${esc(record.id)} · v${number(record.version)}</p><p>${count(p.available_cells)} / ${count(p.bounds?.cells)} fixed parent cells available · work proxy ${count(p.bounds?.estimated_total_work)}. ${esc(human(p.status))}.</p><p class="field-help">${checked ? 'Recorded fresh source/operator reproduction: passed for this exact version/hash.' : 'No passing replay selected for this exact version/hash; displayed values are recorded output.'} Local normalized registry sources and the same numerical backend can be rechecked without models or raw upstream rereads.</p><div class="table-wrap"><table><thead><tr><th>ORIGINAL UTC WINDOW</th><th>VARIANT</th><th>NODES / SUPPORTED / BALANCED EDGES</th><th>REFERENCE EVENTS</th><th>SIGNAL ENERGY</th><th>GRADIENT ENERGY</th><th>CIRCULATION ENERGY</th><th>FRACTIONS GRADIENT / CIRCULATION</th></tr></thead><tbody>${rows || '<tr><td colspan="8">No fixed cell output recorded.</td></tr>'}</tbody></table></div><div class="note">Lexical ID order orients each supported unordered pair. Forward minus reverse named-reference counts cancel balanced activity, but supported zero edges remain. Energies are squared net-count coordinates; fractions are separate dimensionless quantities, not proportions of messages or agents. Zero signals have zero energy and undefined fractions. Unavailable source, budget or backend cells remain unknown. faces=None leaves the face complex unspecified: curl and harmonic components/energies remain unknown. Node universes can vary by window; all fixed cells are retained without ranking or rematching.</div><p class="field-help">Display only: nonzero natural energies with magnitude ≤ 10⁻¹² × max(1, signal squared energy) display as ≈ 0; fractions use absolute 10⁻¹². Other values use six significant digits. Original finite values, including rounding just above one, remain below without clipping.</p><div class="note">Time order is discarded. Algebraic circulation does not establish physical traffic, hierarchy, rumor, chronological relay, continuum Laplace–Beltrami structure, novelty or causality. Potentials are gauge-dependent coordinates, not ranks. Variants and source windows remain dependent; no independent experimental units or behavior/theory promotions are added.</div><div class="action-row"><button class="button" data-action="replay-edge-flow" data-id="${esc(record.id)}" data-version="${number(record.version)}">Fresh edge-count replay · zero model calls</button>${parentLink}</div>${raw({identity:{id:record.id,kind:record.kind,version:record.version,hash:record.hash},source_refs:p.source_refs,implementation_hashes:p.implementation_hashes,configuration:p.configuration,bounds:p.bounds,unknown_reasons:p.unknown_reasons,recorded_proof:checked ? proof : null},'Exact fixed pins, operator declaration and bounds')}${raw(compact,'Original numeric energies/checks and supported directional event pins · no potential rankings')}`);
