  const waitSection=await waitMarkerAuditSection();
  const hodgeSection=await graphHodgeAuditSection();
  const claimControls=claimRecord ? panel('Checked result claims','Finite assertions stay separate from interpretation.',`<div class="selector-bar"><label for="select-claim_audit">Claim audit</label><select class="control" id="select-claim_audit" data-select="claim_audit">${options('claim_audit',claimId)}</select></div>${claimAuditPanel(claimRecord)}`) : panel('Checked result claims','Audit a completed swarm or network result.',`<p class="section-caption">Use “Audit result claims” on a completed wind-tunnel result. Offline mode builds typed claims in code; live mode asks the selected research harness to construct them. The same finite checker validates both.</p><button class="button" data-view="experiments">Open wind tunnel results →</button>`);
  const jobCards=jobs.map(job => { const p=job.payload || {}, outputs=uniqueIds([p.outputs,p.result_ids,p.result_id,p.protocol_id,p.incomplete_result_id]); return `<article class="job-card ${job.status === 'running' ? 'job-running' : ''}"><div class="job-head"><h3>${esc(human(p.action || p.stage || 'Research workflow'))}</h3>${badge(job.status)}</div><p class="mono">${esc(job.id)} · ${esc(date(job.updated))}</p>${p.stage ? `<p>Current stage: <strong>${esc(human(p.stage))}</strong></p>` : ''}${p.progress ? `<p>Completed ${number(p.progress.completed)} of ${number(p.progress.total)} ${p.progress.topology ? 'networks' : 'swarm runs'} · ${esc(topologyNames[p.progress.topology] || '')} · ${esc(contextNames[p.progress.context] || '')}</p>` : ''}${p.error ? `<p class="error-text">${esc(p.error)}</p>` : ''}<div class="job-outputs">${outputs.map(id => `<button class="button-link" data-open="${esc(id)}">${esc(shortId(id))} ↗</button>`).join('')}<button class="button-link" data-trace="${esc(job.id)}">Inspect model/tool audit →</button></div></article>`; }).join('') || '<div class="list-empty">No jobs have run yet.</div>';
