  const harnessCards=(app.state.harnesses || []).map(harness => `<div class="object-row"><div class="row-main"><h3>${esc(harness.id === 'responses' ? 'OpenAI Responses' : 'Codex CLI')}</h3><p>${esc((harness.capabilities || []).map(human).join(' · '))}</p>${harness.limitations?.length ? `<p>${esc(harness.limitations.join(' '))}</p>` : ''}</div>${badge(harness.available ? 'Available' : 'Unavailable',harness.available ? 'cyan' : 'orange')}</div>`).join('');
